// Signs the release build with the owner's own upload key (spec 15.1, D249), not the debug key every developer has.
// android/ is regenerated by `expo prebuild`, so this config plugin writes the signing into android/app/build.gradle
// each time. The key's path, alias and passwords come from the Gradle properties DOKAAN_UPLOAD_STORE_FILE,
// DOKAAN_UPLOAD_STORE_PASSWORD, DOKAAN_UPLOAD_KEY_ALIAS and DOKAAN_UPLOAD_KEY_PASSWORD, kept in
// ~/.gradle/gradle.properties outside both repositories. Without them (CI, another laptop) the release build stays on
// the debug key, as before.
const { withAppBuildGradle } = require("expo/config-plugins");

const MARK = "DOKAAN_UPLOAD_STORE_FILE";

const RELEASE_SIGNING = `        release {
            // The owner's upload key (D249), when ~/.gradle/gradle.properties names it.
            if (findProperty('DOKAAN_UPLOAD_STORE_FILE')) {
                storeFile file(findProperty('DOKAAN_UPLOAD_STORE_FILE'))
                storePassword findProperty('DOKAAN_UPLOAD_STORE_PASSWORD')
                keyAlias findProperty('DOKAAN_UPLOAD_KEY_ALIAS')
                keyPassword findProperty('DOKAAN_UPLOAD_KEY_PASSWORD')
            }
        }
`;

const RELEASE_USES =
  "signingConfig findProperty('DOKAAN_UPLOAD_STORE_FILE') ? signingConfigs.release : signingConfigs.debug";

/** The build.gradle text with the release signing added; unchanged when it is already there. */
function addReleaseSigning(gradle) {
  if (gradle.includes(MARK)) return gradle;

  const configs = gradle.indexOf("signingConfigs {");
  if (configs < 0)
    throw new Error("with-release-signing: no signingConfigs block in android/app/build.gradle");
  const afterConfigs = gradle.indexOf("\n", configs) + 1;
  let text = gradle.slice(0, afterConfigs) + RELEASE_SIGNING + gradle.slice(afterConfigs);

  const buildTypes = text.indexOf("buildTypes {");
  const release = buildTypes < 0 ? -1 : text.slice(buildTypes).search(/\brelease\s*\{/);
  if (release < 0) throw new Error("with-release-signing: no release build type in android/app/build.gradle");
  const start = buildTypes + release;
  const uses = text.indexOf("signingConfig signingConfigs.debug", start);
  const end = text.indexOf("\n        }", start);
  if (uses < 0 || (end >= 0 && uses > end)) {
    throw new Error(
      "with-release-signing: the release build type does not use the debug signing as expected",
    );
  }
  text = text.slice(0, uses) + RELEASE_USES + text.slice(uses + "signingConfig signingConfigs.debug".length);
  return text;
}

function withReleaseSigning(config) {
  return withAppBuildGradle(config, (gradleConfig) => {
    gradleConfig.modResults.contents = addReleaseSigning(gradleConfig.modResults.contents);
    return gradleConfig;
  });
}

module.exports = withReleaseSigning;
module.exports.addReleaseSigning = addReleaseSigning;
